type Reply = { body: unknown; status?: number; etag?: string };
type Table = Record<string, Reply | ((method: string) => Reply)>;

const reply = (route: Route, r: Reply) =>
  route.fulfill({
    status: r.status ?? 200,
    contentType: "application/json",
    headers: r.etag ? { etag: r.etag } : {},
    body: JSON.stringify(r.body),
  });

