export async function stubSetupApi(page: Page) {
  const routes = table();
  await page.route("**/v1/**", async (route) => {
    const path = new URL(route.request().url()).pathname;
    const found = routes[path];
    if (!found) return reply(route, { status: 404, body: { error: { code: "not_found", message: "" } } });
    return reply(route, typeof found === "function" ? found(route.request().method()) : found);
  });
}

/** axe (with colour contrast) finds nothing, every visible button is at least 52px tall and body text is at least 17px. */
export async function expectAccessible(page: Page) {
  const axe = await new AxeBuilder({ page }).withTags(TAGS).analyze();
  expect(axe.violations).toEqual([]);
  const sizes = await page.evaluate(() => {
    const visible = (el: Element) => {
      const box = el.getBoundingClientRect();
      return box.width > 0 && box.height > 0;
    };
    const buttons = [...document.querySelectorAll("main button, main .av-button")]
      .filter(visible)
      .map((el) => ({ text: (el.textContent ?? "").trim(), height: el.getBoundingClientRect().height }));
    const text = [...document.querySelectorAll("main p:not(.av-small), main label, main li, main legend, main input:not([type=radio]):not([type=checkbox]):not([type=file]), main select, main textarea")]
      .filter(visible)
      .map((el) => ({ text: (el.textContent ?? "").trim().slice(0, 40), size: parseFloat(getComputedStyle(el).fontSize) }));
    return { buttons, text, body: parseFloat(getComputedStyle(document.body).fontSize) };
  });
  expect(sizes.body).toBeGreaterThanOrEqual(17);
  expect(sizes.buttons.length).toBeGreaterThan(0);
  expect(sizes.buttons.filter((b) => b.height < 52)).toEqual([]);
  expect(sizes.text.filter((t) => t.size < 17)).toEqual([]);
}
